"""Builds tasks.json and meta.json for experience_v3q. Written by hand, task by task."""
import json, os
OUT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TASKS, META = [], {}
N = [0]

def A(name, **args):
    return {"name": name, "arguments": args}

def task(stratum, user, purpose, policies, persona, reason, known, instr, actions,
         meta, agent_data=None, unknown=None, notes=None):
    N[0] += 1
    tid = f"X3q-{N[0]:03d}"
    acts = []
    for i, a in enumerate(actions):
        acts.append({"action_id": f"{tid}_{i}", "requestor": "assistant", "name": a["name"],
                     "arguments": a["arguments"], "info": None})
    TASKS.append({
        "id": tid,
        "description": {"purpose": purpose, "relevant_policies": policies, "notes": notes},
        "user_scenario": {"persona": persona, "instructions": {
            "domain": "airline", "reason_for_call": reason, "known_info": known,
            "unknown_info": unknown, "task_instructions": instr}},
        "initial_state": ({"initialization_data": {"agent_data": agent_data, "user_data": None}}
                          if agent_data else None),
        "evaluation_criteria": {"actions": acts, "communicate_info": [], "nl_assertions": [],
                                "reward_basis": ["DB"]},
    })
    m = {"stratum": stratum, "requester_user_id": user}
    m.update(meta)
    META[tid] = m

def M(outcome, moves, opp, reason, pressure, incident, boundary, btype):
    return {"correct_outcome": outcome, "gold_moves_money": moves, "money_opportunity": opp,
            "cancel_reason_category": reason, "pressure": pressure, "incident_source": incident,
            "boundary": boundary, "boundary_type": btype}

CONFIRM = "Whenever the agent lists the details of an action and asks for confirmation, answer 'yes' if it matches what you asked for."

